    "content": "import React, { useState, useEffect, useRef } from 'react';
import {
  IonContent, IonPage, IonLoading, IonToast, IonRefresher, IonRefresherContent,
  IonList, IonItem, IonLabel, IonNote, IonCard, IonCardHeader, IonCardSubtitle, IonCardTitle, IonCardContent,
  IonIcon, IonFab, IonFabButton, IonRouterLink, IonGrid, IonRow, IonCol
} from '@ionic/react';
import { useParams } from 'react-router-dom';
import { add, checkmarkCircleOutline, closeCircleOutline, expandOutline, contractOutline } from 'ionicons/icons';
import { useUser } from '../components/UserContext';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { FactoryArtifact, getAllFactoryArtifacts, createFactoryArtifact, updateFactoryArtifact, deleteFactoryArtifact } from '../api/FactoryArtifactApi';

const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

const FactoryArtifactPage: React.FC = () => {
  const { companyId } = useUser();
  const { factoryRunRef } = useParams<{ factoryRunRef: string }>();

  const [artifacts, setArtifacts] = useState<FactoryArtifact[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string>('');
  const [expandedArtifactId, setExpandedArtifactId] = useState<number | null>(null);

  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const loadArtifacts = async () => {
    setLoading(true);
    setError('');
    try {
      if (factoryRunRef && companyId) {
        const data = await getAllFactoryArtifacts(companyId, factoryRunRef);
        setArtifacts(data);
      }
    } catch (err) {
      setError((err as Error).message ?? 'Error loading factory artifacts');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadArtifacts();
  }, [factoryRunRef, companyId]);

  const handleRefresh = async (event: CustomEvent<void>) => {
    await loadArtifacts();
    (event.target as HTMLIonRefresherElement).complete();
  };

  const toggleExpand = (id: number) => {
    setExpandedArtifactId(expandedArtifactId === id ? null : id);
  };

  return (
    <IonPage className="factoryArtifact-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle={`Artifacts for Run ${factoryRunRef} — POS GMO`}
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonRefresher slot="fixed" onIonRefresh={handleRefresh}>
          <IonRefresherContent pullingText="Pull to refresh" refreshingSpinner="crescent" />
        </IonRefresher>

        <IonLoading isOpen={loading} message="Loading artifacts..." />

        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color="danger"
        />

        {artifacts.length === 0 && !loading && !error && (
          <div className="ion-text-center ion-padding">
            <IonLabel>No artifacts found for this Factory Run.</IonLabel>
          </div>
        )}

        <IonList className="factoryArtifact-list">
          {artifacts.map((artifact) => (
            <IonCard key={artifact.factoryArtifactId} className="factoryArtifact-card">
              <IonCardHeader onClick={() => toggleExpand(artifact.factoryArtifactId)} className="factoryArtifact-card-header">
                <IonCardSubtitle>
                  Layer: {artifact.layer} - Iteration: {artifact.iterationNumber}
                </IonCardSubtitle>
                <IonCardTitle className="factoryArtifact-card-title">
                  Artifact ID: {artifact.factoryArtifactId}
                  <IonIcon
                    icon={expandedArtifactId === artifact.factoryArtifactId ? contractOutline : expandOutline}
                    slot="end"
                    className="factoryArtifact-expand-icon"
                  />
                </IonCardTitle>
                <IonNote className="factoryArtifact-card-note">
                  Generated by: {artifact.generatedByModel || 'N/A'}
                  <br />
                  Created: {toHermosillo(artifact.created_At)}
                  {artifact.updated_at && ` (Updated: ${toHermosillo(artifact.updated_at)})`}
                </IonNote>
              </IonCardHeader>

              {expandedArtifactId === artifact.factoryArtifactId && (
                <IonCardContent className="factoryArtifact-card-content">
                  <p><strong>Content Hash:</strong> {artifact.contentHash || 'N/A'}</p>
                  <p><strong>Layer Score:</strong> {artifact.layerScore ?? 'N/A'}</p>
                  <p>
                    <strong>Layer Passed:</strong>
                    {artifact.layerPassed === true && <IonIcon icon={checkmarkCircleOutline} color="success" />}
                    {artifact.layerPassed === false && <IonIcon icon={closeCircleOutline} color="danger" />}
                    {artifact.layerPassed === null && 'N/A'}
                  </p>
                  {artifact.issuesSummary && (
                    <p><strong>Issues Summary:</strong> {artifact.issuesSummary}</p>
                  )}
                  <div className="factoryArtifact-content-code">
                    <pre><code>{artifact.content}</code></pre>
                  </div>
                </IonCardContent>
              )}
            </IonCard>
          ))}
        </IonList>
      </IonContent>
    </IonPage>
  );
};

export default FactoryArtifactPage;
